        vector<int> pre(n + 1);
        for(int i = 1; i <= n; i++) {
            if(i & 1) pre[i] = pre[i - 1] + v[i - 1];
            else pre[i] = pre[i - 1] - v[i - 1];
        }

        vector<int> h = pre;
        sort(h.begin(), h.end());
        h.erase(unique(h.begin(), h.end()), h.end());
        auto get = [&](int x) { return lower_bound(h.begin(), h.end(), x) - h.begin() + 1; };

        FenwickTree fen_ev(h.size()), fen_od(h.size());
        int ans = 0;

        fen_ev.update(get(0), 1);

        for(int i = 1; i <= n; i++) {
            int x = get(pre[i]);
            if(i & 1) {
                ans += fen_ev.query(x - 1);
                fen_od.update(x, 1);
            }
            else {
                ans += fen_od.query(x + 1, h.size());
                fen_ev.update(x, 1);
            }
        }

        cout << ans << endl;
    }
}

#include <bits/stdc++.h>
using namespace std;
#define int long long

const int N = 2e5 + 10;

int n;
vector<int> adj[N];
int mx[N], cnt[N];

void dfs(int u, int par) {
    cnt[u] = (adj[u].size() == 1);

    for(int v : adj[u]) {
        if(v == par) continue;
        dfs(v, u);
        cnt[u] += cnt[v];
    }

    int cur = 0;
    for(int v : adj[u]) {
        if(v == par) continue;
        int w = (cnt[v] & 1) ? 1 : -1;
        cur = max(cur, mx[v] + w);
    }

    mx[u] = cur;
}

